import{d as h,C as n,o as d,c as g,j as i,a as e,E as o,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第5章","description":"《中庸》第 5 章——「道其不行矣夫！」一句叹息，承上启下：由不明，故不行。","frontmatter":{"title":"中庸·第5章","description":"《中庸》第 5 章——「道其不行矣夫！」一句叹息，承上启下：由不明，故不行。","category":"guide","aliases":["第5章","中庸第5章","道其不行矣夫"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-05.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-05.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-05.md"},x=h({...m,setup(p){const t=[{id:"tan",label:"道其不行矣夫",showLabel:!0,sentences:[["子曰：“道其",{text:"不行",glossary:"buxing"},"矣",{text:"夫",glossary:"fu"},"！”"]],note:"孔子只一句长叹：「道其不行矣夫！」——道大概行不通了吧！此章上下文皆无，历来视作承上章「道之不行」而发的感叹，是一个情绪的停顿。"}],r=[{id:"dao",term:"道",pinyin:"dào",meaning:"此处指中庸之道，即前数章所论「中」之所行。"},{id:"qi",term:"其",pinyin:"qí",meaning:"表推测、拟议的语气词，相当于「大概」「恐怕」。"},{id:"buxing",term:"不行",pinyin:"bù xíng",meaning:"不能实行、行不通。"},{id:"fu",term:"夫",pinyin:"fú",meaning:"句末语气词，此处读 fú。「矣夫」连用，感叹语气更重。"}];return(c,a)=>{const l=n("DaoTextReading"),s=n("DaoKeywordCards");return d(),g("div",null,[a[0]||(a[0]=i("h1",{id:"中庸·第5章",tabindex:"-1"},[e("中庸·第5章 "),i("a",{class:"header-anchor",href:"#中庸·第5章","aria-label":'Permalink to "中庸·第5章"'},"​")],-1)),a[1]||(a[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),a[2]||(a[2]=i("p",null,"本章只有六个字，是一声叹息。它承上章「道之不行、不明」而来，也是下一章「舜其大知」的引子。默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),o(l,{colophon:"道其不行矣夫",tone:"ink",sections:t,glossary:r,"default-mode":"slips","aria-label":"中庸·第5章 原文"}),a[3]||(a[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),o(s,{items:[{term:"道",pinyin:["dào"],meaning:"此处指中庸之道，即前数章所论「中」之所行。"},{term:"其",pinyin:["qí"],meaning:"表推测、拟议的语气词，相当于「大概」「恐怕」。"},{term:"不行",pinyin:["bù","xíng"],meaning:"不能实行、行不通。"},{term:"夫",pinyin:["fú"],meaning:"句末语气词，此处读 fú。「矣夫」连用，感叹语气更重。"}]}),a[4]||(a[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p>孔子说：「道大概是不能实行了吧！」</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第五章只有六个字，是一声<strong>叹息</strong>。它夹在中间：前有第四章说「道之不行、不明」的原因，后有第六章举舜的「大知」。所以这一句既是承接，也是转折。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它标出「不明 → 不行」这条链</strong>：朱注解此章说「道不可离，人自不察，是以有过不及之弊」，又承上章说「<strong>由不明，故不行</strong>」——之所以行不通，是因为看不清。这一句把两层因果说透了。</li><li><strong>叹息也是一种诚实</strong>：孔子并非不知道原因（上一章刚说过），明知原因而仍发此叹，说明「知道原因」与「能把道行起来」之间，还隔着人和时势。</li><li><strong>它是全篇的节奏点</strong>：第十一、十二章的转折由此起——一句短叹，把问题摊开，接着才有「舜其大知」「君子之道费而隐」的展开。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>行不通时先问「明不明」</strong>：把「做不到」当成结果，把「看不清」当成原因，回头查一查。</li><li><strong>允许一声叹息</strong>：看清难处，不必急着给结论；承认真实处境，是继续走的前提。</li><li><strong>短句更见分量</strong>：有些话说尽了，就只剩一句。这一章的分量，正在它不肯多说。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子叹了一口气：道大概是不能实行了吧。</p><p>上一章刚讲过道为什么行不通（过与不及），这一章却只剩一句感叹。<strong>明知原因，仍不免一叹</strong>——因为「知道原因」解决不了「人做不做」。朱子把这条线串得很清楚：由不明，故不行。看得清，才有可能走得通。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「道其不行矣夫」——孔子是失望，还是承认？这两种读法会带来什么不同的行动？</li><li>「由不明，故不行」——在我身上，有没有「看清之后才走得通」的具体例子？</li><li>这一章只有六个字，为什么还能立为一章？（短句在经典里的位置）</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-04">中庸·第4章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-06">中庸·第6章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',19))])}}});export{b as __pageData,x as default};
